import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";

const server = new McpServer({ name: "weather-server", version: "1.0.0" });

server.tool(
  "get_weather",
  "Get the current weather for a named city",
  { city: z.string().describe("City name, for example Paris") },
  async ({ city }) => {
    const data = await fetchWeather(city);
    return {
      content: [{ type: "text", text: "Weather in " + city + ": " + data.summary }]
    };
  }
);

return {
  content: [
    { type: "text", text: "Weather in Paris: 18C, light rain" }
  ]
};

server.tool(
  "get_weather",
  "Get the current weather for a named city",
  { city: z.string() },
  async ({ city }) => {
    try {
      const data = await fetchWeather(city);
      return { content: [{ type: "text", text: data.summary }] };
    } catch (err) {
      return {
        isError: true,
        content: [{ type: "text", text: "Could not fetch weather for " + city }]
      };
    }
  }
);

